import{_ as r,o as t,c as o,a2 as a}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"JipperOverlayer","description":"","frontmatter":{"title":"JipperOverlayer","order":6},"headers":[],"relativePath":"mods/jipperoverlayer.md","filePath":"mods/jipperoverlayer.md","lastUpdated":1786957039000}'),n={name:"mods/jipperoverlayer.md"};function i(l,e,s,d,p,g){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="jipperoverlayer" tabindex="-1">JipperOverlayer <a class="header-anchor" href="#jipperoverlayer" aria-label="Permalink to &quot;JipperOverlayer&quot;">​</a></h1><blockquote><p>An ADOFAI in-game <strong>screen overlay</strong> Mod: real-time display of progress, accuracy, BPM, combo, and judgment info. Supports <strong>Unity Mod Manager</strong> and <strong>MelonLoader</strong>, with settings UI in English / Korean / Chinese.</p><p>Project: <a href="https://github.com/adofaiex/JipperOverlayer" target="_blank" rel="noreferrer">https://github.com/adofaiex/JipperOverlayer</a></p></blockquote><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><strong>Real-time overlay</strong>: progress, accuracy (Accuracy / XAccuracy), music/map time, checkpoint, best record</li><li><strong>BPM display</strong>: floor BPM, current BPM, KPS, with pseudo BPM detection</li><li><strong>Combo counter</strong>: animated combo display + color gradient</li><li><strong>Judgment display</strong>: Miss / Bad / Good / Perfect and other hit breakdowns</li><li><strong>Time scaling</strong>: current timing scale percentage</li><li><strong>Attempt tracking</strong>: per-map attempt count (persisted)</li><li><strong>Progress bar</strong>: visual progress indicator</li><li><strong>Jongyeol mode</strong>: extended overlay with FPS, status, death count, start position, timing analysis, hidden debug text</li><li><strong>Two-player support</strong>: separate display for each player in multiplayer</li><li><strong>Text effects</strong>: global shadow (TMP Underlay) and outline, RGBA color picker, width/softness sliders</li><li><strong>Per-section fonts</strong>: independent font and size per overlay position (Main / BPM / Judgement / Combo / Timing / Attempt)</li><li><strong>UI patch toggles</strong>: beta watermark, level name position, auto text rearrangement can be toggled independently</li><li><strong>Color editor</strong>: interactive gradient editor for all overlay colors</li><li><strong>XPerfect integration</strong>: optional enhanced perfect display (requires <a href="https://github.com/8100print/XPerfect" target="_blank" rel="noreferrer">XPerfect</a>)</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><h3 id="unity-mod-manager" tabindex="-1">Unity Mod Manager <a class="header-anchor" href="#unity-mod-manager" aria-label="Permalink to &quot;Unity Mod Manager&quot;">​</a></h3><ol><li>Install <a href="https://www.nexusmods.com/site/mods/21" target="_blank" rel="noreferrer">UMM</a></li><li>Download the <strong>UMM</strong> version from <a href="https://github.com/adofaiex/JipperOverlayer/releases" target="_blank" rel="noreferrer">Releases</a></li><li>Install via UMM, or extract to <code>ADOFAI/Mods/JipperOverlayer/</code></li></ol><h3 id="melonloader" tabindex="-1">MelonLoader <a class="header-anchor" href="#melonloader" aria-label="Permalink to &quot;MelonLoader&quot;">​</a></h3><ol><li>Install <a href="https://melonwiki.xyz/" target="_blank" rel="noreferrer">MelonLoader</a></li><li>Download the <strong>MelonLoader</strong> version</li><li>Extract to <code>ADOFAI/Mods/JipperOverlayer-melon/</code></li><li>Press <strong>F7</strong> in-game to open settings (rebindable)</li></ol><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Steam version of ADOFAI</li><li>UnityModManager 0.22.14+ <strong>or</strong> MelonLoader</li><li>Supports game versions v136 and v141+</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><blockquote><p>📝 To be supplemented (feel free to report in the repository Issues)</p></blockquote>',13)])])}const u=r(n,[["render",i]]);export{h as __pageData,u as default};
